        const m = {
          'spectrum': ScreenType.spectrum,
          'polo': ScreenType.polo,
          'dot': ScreenType.dot,
          'void': ScreenType.void_,
          'void_': ScreenType.void_,
          'cassette': ScreenType.cassette,
        };
        final t = m[value];
        if (t == null) {
          return _error(
